{"path": "/tmp/sv-5aaa94890ed440979fc1bc448b212af1/Components/Pages/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="Title" @bind:event="oninput" />
    <input type="text" placeholder="Assignee" @bind="Assignee" @bind:event="oninput" />
    <select @bind="Priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="DueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="SaveAsync" disabled="@IsSaving">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
    @if (!string.IsNullOrEmpty(Error))
    {
        <p class="form-error">@Error</p>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ColumnStatus { get; set; } = default!;
    [Parameter] public EventCallback OnCancel { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private string Title = string.Empty;
    private string Assignee = string.Empty;
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);
    private bool IsSaving;
    private string? Error;

    private async Task SaveAsync()
    {
        if (string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Assignee))
        {
            Error = "Title and Assignee are required.";
            return;
        }

        IsSaving = true;
        Error = null;
        try
        {
            var created = await TaskService.CreateTaskAsync(Title, Assignee, Priority, DueDate);
            // The service creates with default status; if the column differs, update it
            if (created.Status != ColumnStatus)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, ColumnStatus);
                created = created with { Status = ColumnStatus };
            }
            await OnTaskCreated.InvokeAsync(created);
        }
        catch (Exception ex)
        {
            Error = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            IsSaving = false;
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}
"}

{"path": "/tmp/sv-5aaa94890ed440979fc1bc448b212af1/Components/Pages/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="@(ColumnIndex > 0)"
                      ShowMoveRight="@(ColumnIndex < 2)"
                      OnMove="OnMoveTask" />
        }
    </div>

    <div class="column-footer">
        @if (ShowAddForm)
        {
            <AddTaskForm ColumnStatus="@ColumnName"
                         TaskService="TaskService"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => ShowAddForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => ShowAddForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool ShowAddForm;

    private async Task HandleTaskCreated(TaskItem task)
    {
        ShowAddForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}
"}

